pub fn append_array(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Prevent usize overflow when computing the final length/capacity.
    let total_len = a
        .len()
        .checked_add(b.len())
        .expect("length overflow when concatenating vectors");

    let mut c: Vec<i32> = Vec::with_capacity(total_len);

    // Preserve order: a first, then b.
    c.extend(a);
    c.extend(b);

    // At this point:
    // - c.len() == total_len
    // - indices [0..len(a)) match a's original order
    // - indices [len(a)..len(a)+len(b)) match b's original order
    c
}